-- Rollback-only statistics and administration checks with fabricated records.
begin;
create temporary table summary_test_results(name text,passed boolean);
do $$
declare actor uuid:=gen_random_uuid();sid uuid:=gen_random_uuid();bank uuid;card uuid;foreign_account uuid;category uuid;purchase uuid;refund uuid;tout uuid;tin uuid;batch uuid;prefix text:='mock-summary-'||gen_random_uuid();r jsonb;s jsonb;before_rows jsonb;after_rows jsonb;n integer;
begin
 insert into auth.users(id,email,email_confirmed_at,is_anonymous,created_at,updated_at) values(actor,'mock-summary-'||actor||'@example.invalid',now(),false,now(),now());insert into household_private.memberships(user_id,status,role) values(actor,'approved','member');insert into auth.sessions(id,user_id,aal) values(sid,actor,'aal1');insert into auth.mfa_amr_claims(id,session_id,authentication_method,created_at,updated_at) values(gen_random_uuid(),sid,'passkey',now(),now());perform set_config('request.jwt.claims',jsonb_build_object('sub',actor,'session_id',sid,'role','authenticated')::text,true);
 insert into household_private.accounts(name,kind,currency) values(prefix||' bank','checking','XSM') returning id into bank;insert into household_private.accounts(name,kind,currency) values(prefix||' card','credit','XSM') returning id into card;insert into household_private.accounts(name,kind,currency) values(prefix||' foreign','checking','YSM') returning id into foreign_account;insert into household_private.categories(name) values(prefix||' groceries') returning id into category;
 insert into household_private.transactions(account_id,category_id,date,description,amount_minor,fingerprint,needs_attention) select bank,category,'2026-08-01'::date+(i-1),prefix||' main purchase '||i,-i*100,prefix||'-p-'||i,i=1 from generate_series(1,65) i;
 select id into purchase from household_private.transactions where fingerprint=prefix||'-p-65';
 insert into household_private.transactions(account_id,date,description,amount_minor,fingerprint) values(bank,'2026-07-31',prefix||' main salary',100000,prefix||'-salary');
 insert into household_private.transactions(account_id,date,description,amount_minor,fingerprint) values(card,'2026-10-05',prefix||' main refund',2500,prefix||'-refund') returning id into refund;
 perform public.household_budget_v1('budget_link_refund',jsonb_build_object('currency','XSM','purchase_id',purchase,'purchase_revision',1,'refund_id',refund,'refund_revision',1,'amount_minor',2500));
 insert into household_private.transactions(account_id,date,description,amount_minor,fingerprint) values(bank,'2026-10-06',prefix||' main transfer out',-10000,prefix||'-out') returning id into tout;insert into household_private.transactions(account_id,date,description,amount_minor,fingerprint) values(card,'2026-10-06',prefix||' main transfer in',10000,prefix||'-in') returning id into tin;
 perform public.household_v1('link_transfer',jsonb_build_object('id',tout,'revision',1,'peer_id',tin,'peer_revision',1,'flow_type','transfer'));
 insert into household_private.transactions(account_id,date,description,amount_minor,fingerprint) values(foreign_account,'2026-08-01',prefix||' foreign expense',-999999,prefix||'-foreign');
 insert into household_private.transactions(account_id,date,description,amount_minor,fingerprint,deleted_at) values(bank,'2026-09-01',prefix||' main trashed expense',-900000,prefix||'-trash',now());
 select jsonb_agg(to_jsonb(t) order by id) into before_rows from household_private.transactions t where description like prefix||'%';
 r:=public.household_v1('list_ledger_transactions',jsonb_build_object('query',prefix||' main','limit',1,'offset',0));s:=r->'summary';
 if r->>'total'<>'69' or jsonb_array_length(r->'rows')<>1 or s->>'transaction_count'<>'69' or s->>'transfer_count'<>'2' or s->>'needs_attention_count'<>'1' then raise exception 'Full matching-set summary/count failed: %',s;end if;
 if s->'currencies'->0->>'income_minor'<>'100000' or s->'currencies'->0->>'spending_minor'<>'212000' or s->'currencies'->0->>'net_minor'<>'-112000' then raise exception 'Income, partial refund, expense or transfer exclusion failed: %',s;end if;
 -- 65 purchases sum to 214500; the linked 2500 refund leaves 212000.
 if s->'currencies'->0->>'average_expense_minor'<>'3300' or s->'currencies'->0->>'average_transaction_minor'<>'4731' or s->'currencies'->0->'largest_expense'->>'amount_minor'<>'-6500' or s->'currencies'->0->'smallest_expense'->>'amount_minor'<>'-100' then raise exception 'Exact averages/extremes failed: %',s;end if;
 if s->'first_transaction'->>'date'<>'2026-07-31' or s->'last_transaction'->>'date'<>'2026-10-06' then raise exception 'First/last record failed';end if;
 r:=public.household_v1('list_ledger_transactions',jsonb_build_object('query',prefix||' main','limit',1,'offset',50,'sort','amount','direction','asc'));if r->'summary'<>s then raise exception 'Pagination or sorting changed summary';end if;
 r:=public.household_v1('list_ledger_transactions',jsonb_build_object('query',prefix||' main','date_from','2026-08-01','date_to','2026-08-31','limit',1));if r->'summary'->>'transaction_count'<>'31' or r->'summary'->'currencies'->0->>'spending_minor'<>'49600' then raise exception 'Inclusive date filters diverged from table';end if;
 r:=public.household_v1('list_ledger_transactions',jsonb_build_object('query',prefix||' main','category_id',category,'limit',1));if r->'summary'->>'transaction_count'<>'65' or r->'summary'->'currencies'->0->>'spending_minor'<>'214500' then raise exception 'Filtered-out refund was applied to purchases';end if;
 r:=public.household_v1('list_ledger_transactions',jsonb_build_object('query',prefix||' main','account_id',bank,'limit',1));if r->'summary'->'currencies'->0->>'spending_minor'<>'214500' then raise exception 'Bank-account filter included credit on another account';end if;
 r:=public.household_v1('list_ledger_transactions',jsonb_build_object('query',prefix||' main','review','needs_attention','limit',1));if r->'summary'->>'transaction_count'<>'1' or r->'summary'->'currencies'->0->>'spending_minor'<>'100' then raise exception 'Review filter diverged';end if;
 r:=public.household_v1('list_ledger_transactions',jsonb_build_object('query',prefix,'limit',1));if jsonb_array_length(r->'summary'->'currencies')<>2 then raise exception 'Currencies were combined';end if;
 r:=public.household_v1('list_ledger_transactions',jsonb_build_object('query',prefix||' main','trash_only',true,'limit',1));if r->'summary'->>'transaction_count'<>'1' or r->'summary'->>'trash_only'<>'true' or r->'summary'->'currencies'->0->>'spending_minor'<>'900000' then raise exception 'Trash preview mixed active records';end if;
 r:=public.household_v1('list_ledger_transactions',jsonb_build_object('query',prefix||' no matches','limit',1));if r->'summary'->>'transaction_count'<>'0' or jsonb_array_length(r->'summary'->'currencies')<>0 then raise exception 'Empty result fabricated amounts';end if;
 select jsonb_agg(to_jsonb(t) order by id) into after_rows from household_private.transactions t where description like prefix||'%';if before_rows<>after_rows then raise exception 'Summary changed financial records';end if;
 insert into summary_test_results values('full filtered totals, exact averages/extremes, currencies, refunds and transfer exclusion',true),('pagination/sorting invariance, date/category/account/review filters, Trash and source preservation',true);
 update household_private.transactions set amount_minor=3500 where id=refund;
 r:=public.household_v1('list_ledger_transactions',jsonb_build_object('query',prefix||' main','limit',1));if r->'summary'->'currencies'->0->>'review_credits_minor'<>'1000' or r->'summary'->'currencies'->0->>'income_minor'<>'100000' then raise exception 'Refund remainder counted as income';end if;
 insert into household_private.transactions(account_id,date,description,amount_minor,fingerprint) values(bank,'2030-01-01',prefix||' future',10,prefix||'-future');
 r:=public.household_v1('list_ledger_transactions',jsonb_build_object('query',prefix||' future','limit',1));if r->'summary'->'currencies'->0->>'income_minor'<>'10' then raise exception 'Summary silently omitted future records in table';end if;
 perform public.household_budget_v1('budget_create_month','{"month":"2026-10","currency":"XSM","refund_timing":"received","settings_revision":0,"copy_from":null}');
 perform public.household_budget_v1('budget_save_line',jsonb_build_object('month','2026-10','currency','XSM','plan_revision',1,'category_id',category,'role','income','planned_minor',0,'rollover_mode','reset','cap_minor',null));
 r:=public.household_v1('list_ledger_transactions',jsonb_build_object('query',prefix||' main','limit',1));if r->'summary'->>'money_error' is null or jsonb_array_length(r->'summary'->'currencies')<>0 or r->>'total'<>'69' then raise exception 'Income/refund conflict was hidden or table was discarded';end if;
 insert into summary_test_results values('known-refund remainder, future table records and visible income/refund conflict',true);
 insert into household_private.import_batches(account_id,created_by,selected_count) values(bank,actor,1) returning id into batch;insert into household_private.staged_rows(batch_id,line,date,description,amount_minor,fingerprint) values(batch,2,'2026-08-01','Mock CSV item',-100,prefix||'-csv');
 r:=public.household_admin_v1('admin_get_transfer_logs','{"stream":"imports","limit":50}');if not exists(select 1 from jsonb_array_elements(r->'rows') e where e->>'id'=batch::text and e->>'status'='staged' and e->>'expected_count'='1') then raise exception 'Staged CSV was not logged';end if;
 insert into household_private.audit_events(actor_id,action,target_id) values(actor,'export_csv',batch);r:=public.household_admin_v1('admin_get_transfer_logs','{"stream":"exports","limit":50}');if not exists(select 1 from jsonb_array_elements(r->'rows') e where e->>'target_id'=batch::text) or r->>'downloads_tracked'<>'false' then raise exception 'Recorded export or tracking limits lost';end if;
 begin perform public.household_admin_v1('admin_get_transfer_logs','{"stream":"sql"}');raise exception 'Invalid stream accepted';exception when invalid_parameter_value then null;end;
 begin perform public.household_admin_v1('admin_get_transfer_logs','{"limit":5000}');raise exception 'Unbounded log read accepted';exception when invalid_parameter_value then null;end;
 execute 'set local role authenticated';r:=public.household_admin_v1('admin_get_transfer_logs','{"stream":"imports"}');execute 'reset role';
 if has_function_privilege('anon','public.household_admin_v1(text,jsonb)','EXECUTE') or has_table_privilege('authenticated','household_private.import_batches','SELECT') then raise exception 'Administration grants too broad';end if;
 update household_private.memberships set status='removed' where user_id=actor;begin perform public.household_admin_v1('admin_get_transfer_logs','{}');raise exception 'Removed member read logs';exception when insufficient_privilege then null;end;
 insert into summary_test_results values('paged import/export metadata, explicit tracking limits and approved passkey-only private access',true);
end $$;
select * from summary_test_results order by name;
rollback;
